<template><section class="viewport" data-testid="robot-viewport"><div class="viewport-tools" data-testid="transform-toolbar"><button @click="store.clearSelection()">Q</button><button @click="store.transformMode='translate'">移动 W</button><button @click="store.transformMode='rotate'">旋转 E</button><button @click="store.transformMode='scale'">缩放 R</button><button @click="store.transformSpace=store.transformSpace==='local'?'world':'local'">{{store.transformSpace==='local'?'局部':'世界'}} X</button><button @click="store.snapEnabled=!store.snapEnabled">吸附 {{store.snapEnabled?'开':'关'}}</button><button @click="store.selectionLevel=store.selectionLevel==='link'?'geometry':'link'">{{store.selectionLevel==='link'?'Link 级':'几何级'}}</button><button @click="store.editSemantic=store.editSemantic==='assembly'?'kinematic':'assembly'">{{store.editSemantic==='assembly'?'装配编辑':'运动学编辑'}}</button><button @click="fitView">聚焦 F</button><span>{{store.scene.robotId||'空场景'}}</span></div><div ref="container" class="canvas-host"></div><PerformancePanel v-if="debugPerformance"/><div v-if="!store.scene.robotId" class="viewport-empty"><h2>三维机器人工作区</h2><p>导入 URDF、Xacro 或 MJCF 模型开始编辑</p><el-button type="primary" @click="openPicker">选择模型文件</el-button></div><div class="viewport-hint">单击选择 · W移动 · E旋转 · R缩放 · Ctrl+Z撤销</div></section></template>
<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref,watch} from 'vue';import * as THREE from 'three';import {OrbitControls} from 'three/examples/jsm/controls/OrbitControls.js';import {TransformControls} from 'three/examples/jsm/controls/TransformControls.js';import {useEditorStore} from '@/stores/editor';import {pickPath} from '@/api/models';import type {TransformTarget} from '@/api/transforms';import {RenderScheduler} from '@/runtime/RenderScheduler';import {JointController} from '@/runtime/JointController';import type {JointRuntime,RobotRuntimeIndex} from '@/runtime/RobotRuntimeIndex';import {ResourceCache} from '@/runtime/ResourceCache';import {registerJointPreview} from '@/runtime/jointRuntimeBridge';import {performanceMetrics} from '@/runtime/PerformanceMetrics';import PerformancePanel from '@/components/debug/PerformancePanel.vue'
const store=useEditorStore(),container=ref<HTMLElement>(),debugPerformance=new URLSearchParams(location.search).get('debugPerformance')==='1';let renderer:THREE.WebGLRenderer,scene:THREE.Scene,camera:THREE.PerspectiveCamera,orbit:OrbitControls,gizmo:TransformControls,scheduler:RenderScheduler,runtime:RobotRuntimeIndex|undefined,controller:JointController|undefined,outline:THREE.BoxHelper|undefined,unregisterPreview=()=>{};const cache=new ResourceCache(),proxy=new THREE.Object3D(),down=new THREE.Vector2();let dragging=false,selectedParentWorld=new THREE.Matrix4(),buildToken=0,lastFrame=performance.now();const resourceRefs:string[]=[]
const rotation=(r:number[])=>new THREE.Matrix4().makeRotationZ(r[2]||0).multiply(new THREE.Matrix4().makeRotationY(r[1]||0)).multiply(new THREE.Matrix4().makeRotationX(r[0]||0));function apply(o:THREE.Object3D,p:number[],r:number[]){o.position.set(...p as [number,number,number]);o.quaternion.setFromRotationMatrix(rotation(r));o.updateMatrix()}
function primitive(kind:string,size:number[],index:number){const material=new THREE.MeshStandardMaterial({color:new THREE.Color().setHSL(.54,index%5*.04+.38,.52),roughness:.55});let geometry:THREE.BufferGeometry;if(kind==='sphere')geometry=new THREE.SphereGeometry(size[0]||.04);else if(kind==='cylinder')geometry=new THREE.CylinderGeometry(size[0]||.04,size[0]||.04,size[1]||.08,20);else geometry=new THREE.BoxGeometry(...(size.length>=3?size:[.08,.08,.08]) as [number,number,number]);return new THREE.Mesh(geometry,material)}
async function buildRuntime(){const token=++buildToken;disposeRuntime();performanceMetrics.increment('sceneRebuilds');const root=new THREE.Group(),links=new Map<string,THREE.Object3D>(),joints=new Map<string,JointRuntime>(),visuals=new Map<string,THREE.Object3D>(),collisions=new Map<string,THREE.Object3D>();root.name='robot-runtime';apply(root,store.scene.rootTransform.xyz,store.scene.rootTransform.rpy);for(const [linkIndex,link] of store.scene.links.entries()){const linkObject=new THREE.Group();linkObject.name=link.name;linkObject.userData={entityType:'link',entityId:link.id};links.set(link.id,linkObject);for(const visual of link.visuals){let object:THREE.Object3D;try{if(visual.resource){object=await cache.acquire(visual.resource);resourceRefs.push(visual.resource)}else object=primitive(visual.kind,visual.size,linkIndex)}catch{object=primitive(visual.kind,visual.size,linkIndex)}if(token!==buildToken)return;apply(object,visual.origin.xyz,visual.origin.rpy);object.scale.set(...visual.scale as [number,number,number]);object.traverse(item=>item.userData={entityType:visual.entityType,entityId:visual.id,linkId:link.id});linkObject.add(object);(visual.entityType==='collision'?collisions:visuals).set(visual.id,object)}}for(const joint of store.scene.joints){const parent=links.get(joint.parent),child=links.get(joint.child);if(!parent||!child)continue;const originObject=new THREE.Group(),motionObject=new THREE.Group();apply(originObject,joint.origin.xyz,joint.origin.rpy);originObject.add(motionObject);motionObject.add(child);parent.add(originObject);const value=store.jointValues[joint.id]??joint.value??0,axis=new THREE.Vector3(...joint.axis as [number,number,number]).normalize();const item:JointRuntime={id:joint.id,type:joint.type,originObject,motionObject,axis,lower:joint.limit.lower,upper:joint.limit.upper,currentValue:value,childLinkObject:child};joints.set(joint.id,item);if(joint.type==='prismatic')motionObject.position.copy(axis).multiplyScalar(value);else if(!['fixed','planar','floating'].includes(joint.type))motionObject.quaternion.setFromAxisAngle(axis,value)}for(const id of store.scene.rootLinks){const item=links.get(id);if(item)root.add(item)}scene.add(root);runtime={modelId:store.scene.robotId||'',rootObject:root,linksById:links,jointsById:joints,visualsById:visuals,collisionsById:collisions};controller=new JointController(runtime,scheduler);unregisterPreview();unregisterPreview=registerJointPreview((id,value)=>controller!.setJoint(id,value));fitView();attachSelection();scheduler.invalidate()}
function disposeRuntime(){unregisterPreview();controller=undefined;if(runtime){scene?.remove(runtime.rootObject);runtime=undefined}for(const url of resourceRefs.splice(0))void cache.release(url);if(outline){scene.remove(outline);outline.dispose();outline=undefined}}
function selectedObject(){if(!runtime||!store.selectedType||!store.selectedId)return;if(store.selectedType==='model_instance')return runtime.rootObject;if(store.selectedType==='joint'||store.selectedType==='assembly_connection')return runtime.jointsById.get(store.selectedId)?.childLinkObject;return(store.selectedType==='link'?runtime.linksById:store.selectedType==='collision'?runtime.collisionsById:runtime.visualsById).get(store.selectedId)}
function attachSelection(){gizmo?.detach();if(outline){scene.remove(outline);outline.dispose();outline=undefined}const object=selectedObject();if(!object){scheduler?.invalidate();return}outline=new THREE.BoxHelper(object,0x39d7ff);scene.add(outline);if(store.selectedType==='link'&&store.editSemantic==='assembly'){scheduler.invalidate();return}object.updateWorldMatrix(true,false);object.matrixWorld.decompose(proxy.position,proxy.quaternion,proxy.scale);const joint=store.selectedType==='link'?[...runtime!.jointsById.values()].find(x=>x.childLinkObject===object):runtime!.jointsById.get(store.selectedId!);selectedParentWorld.copy(joint?.originObject.parent?.matrixWorld??object.parent?.matrixWorld??new THREE.Matrix4());scene.add(proxy);gizmo.attach(proxy);scheduler.invalidate()}
function targetTransform(){proxy.updateMatrixWorld();const local=selectedParentWorld.clone().invert().multiply(proxy.matrixWorld),p=new THREE.Vector3(),q=new THREE.Quaternion(),s=new THREE.Vector3();local.decompose(p,q,s);const e=new THREE.Euler().setFromQuaternion(q,'XYZ');return{xyz:[p.x,p.y,p.z],rpy:[e.x,e.y,e.z],scale:[s.x,s.y,s.z]}}
function fitView(){if(!runtime)return;const box=new THREE.Box3().setFromObject(runtime.rootObject);if(box.isEmpty())return;const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()).length();camera.position.copy(center).add(new THREE.Vector3(1,1,.7).normalize().multiplyScalar(Math.max(size*2.2,.5)));orbit.target.copy(center);orbit.update();scheduler.invalidate()}
async function openPicker(){const result=await pickPath('file');if(result.path)await store.open({path:result.path})}
function pick(event:PointerEvent){if(dragging||!runtime||down.distanceTo(new THREE.Vector2(event.clientX,event.clientY))>4)return;const rect=renderer.domElement.getBoundingClientRect(),mouse=new THREE.Vector2((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1),ray=new THREE.Raycaster();ray.setFromCamera(mouse,camera);const hit=ray.intersectObject(runtime.rootObject,true).find(x=>x.object.userData.entityId);if(!hit){store.clearSelection();return}const data=hit.object.userData,linkId=data.linkId||data.entityId;if(store.selectionLevel==='geometry')store.select(data.entityType,data.entityId);else{const link=store.scene.links.find(x=>x.id===linkId);if(link?.parentJoint&&store.scene.assemblyJoints.includes(link.parentJoint))store.select('assembly_connection',link.parentJoint);else if(store.scene.rootLinks.includes(linkId))store.select('model_instance',store.scene.robotId!);else store.select('link',linkId)}}
function key(event:KeyboardEvent){if((event.target as HTMLElement)?.matches('input,textarea,[contenteditable=true]'))return;const k=event.key.toLowerCase();if((event.ctrlKey||event.metaKey)&&k==='z'){event.preventDefault();event.shiftKey?store.redo():store.undo();return}if((event.ctrlKey||event.metaKey)&&k==='y'){event.preventDefault();store.redo();return}if(k==='w')store.transformMode='translate';if(k==='e')store.transformMode='rotate';if(k==='r')store.transformMode='scale';if(k==='x')store.transformSpace=store.transformSpace==='local'?'world':'local';if(k==='q'||k==='escape')store.clearSelection();if(k==='f'||k==='home')fitView()}
onMounted(()=>{scene=new THREE.Scene();scene.background=new THREE.Color(0x101923);camera=new THREE.PerspectiveCamera(42,1,.001,1000);camera.up.set(0,0,1);camera.position.set(2,2,1.4);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=false;container.value!.appendChild(renderer.domElement);orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=false;scheduler=new RenderScheduler(time=>{const start=performance.now();orbit.update();renderer.render(scene,camera);performanceMetrics.recordFrame(time-lastFrame);lastFrame=time;performanceMetrics.recordRender(performance.now()-start,renderer.info.render.calls,renderer.info.render.triangles)});orbit.addEventListener('start',()=>scheduler.startContinuous('camera'));orbit.addEventListener('change',()=>scheduler.invalidate());orbit.addEventListener('end',()=>scheduler.stopContinuous('camera'));gizmo=new TransformControls(camera,renderer.domElement);scene.add(gizmo.getHelper());gizmo.addEventListener('dragging-changed',event=>{dragging=Boolean(event.value);orbit.enabled=!dragging;if(dragging)scheduler.startContinuous('transform-gizmo');else{scheduler.stopContinuous('transform-gizmo');if(store.selectedType&&store.selectedId)void store.commit(store.selectedType as TransformTarget,store.selectedId,targetTransform())}});gizmo.addEventListener('objectChange',()=>{const object=selectedObject();if(object){object.parent!.worldToLocal(proxy.position.clone());object.position.copy(proxy.position);object.quaternion.copy(proxy.quaternion);object.updateMatrix();outline?.update();scheduler.invalidate()}});scene.add(new THREE.HemisphereLight(0xddeeff,0x1b2636,2.1),new THREE.DirectionalLight(0xffffff,2.4));const grid=new THREE.GridHelper(10,20,0x365268,0x23394c);grid.rotation.x=Math.PI/2;scene.add(grid,new THREE.AxesHelper(.5));renderer.domElement.addEventListener('pointerdown',event=>down.set(event.clientX,event.clientY));renderer.domElement.addEventListener('pointerup',pick);window.addEventListener('keydown',key);const resize=()=>{const width=container.value!.clientWidth,height=container.value!.clientHeight;renderer.setSize(width,height,false);camera.aspect=width/Math.max(height,1);camera.updateProjectionMatrix();scheduler.invalidate()};new ResizeObserver(resize).observe(container.value!);resize();if(store.scene.robotId)void buildRuntime()})
watch(()=>store.sceneGeneration,()=>void buildRuntime());watch(()=>[store.selectedType,store.selectedId,store.editSemantic],attachSelection);watch(()=>store.transformMode,value=>gizmo?.setMode(value));watch(()=>store.transformSpace,value=>gizmo?.setSpace(value));watch(()=>store.snapEnabled,value=>{gizmo.setTranslationSnap(value?.01:null);gizmo.setRotationSnap(value?THREE.MathUtils.degToRad(5):null);gizmo.setScaleSnap(value?.05:null)});onBeforeUnmount(()=>{buildToken++;window.removeEventListener('keydown',key);disposeRuntime();scheduler.dispose();gizmo.dispose();orbit.dispose();renderer.dispose();cache.dispose()})
watch(()=>store.renderQuality,value=>{if(!renderer)return;const max=value==='performance'?1:value==='quality'?2:1.5;renderer.setPixelRatio(Math.min(devicePixelRatio,max));renderer.shadowMap.enabled=value==='quality';scheduler.invalidate()})
async function benchmarkRuntime(iterations=120){if(!controller||!runtime)throw new Error('Runtime not ready');const joint=[...runtime.jointsById.values()].find(item=>!['fixed','planar','floating'].includes(item.type));if(!joint)throw new Error('No movable joint');const samples:number[]=[];const started=performance.now();for(let i=0;i<iterations;i++){await new Promise<void>(resolve=>requestAnimationFrame(()=>{const before=performance.now();controller!.setJoint(joint.id,Math.sin(i*.1)*Math.min(joint.upper??1,.8));samples.push(performance.now()-before);resolve()}))}samples.sort((a,b)=>a-b);const elapsed=performance.now()-started;return{iterations,totalMs:elapsed,fps:iterations/elapsed*1000,averageUpdateMs:samples.reduce((a,b)=>a+b,0)/samples.length,p50UpdateMs:samples[Math.floor(samples.length*.5)],p95UpdateMs:samples[Math.floor(samples.length*.95)],p99UpdateMs:samples[Math.floor(samples.length*.99)],metrics:performanceMetrics.snapshot()}}
if(debugPerformance)(window as unknown as {benchmarkJointRuntime:(iterations?:number)=>Promise<unknown>}).benchmarkJointRuntime=benchmarkRuntime
</script>
